                        tTimeout = setTimeout(() => { isDeleting = true; type(); }, pauseTime);
                    }
                } else {
                    if (i > 0) {
                        element.textContent = text.substring(0, i - 1); i--;
                        tTimeout = setTimeout(type, deleteSpeed);
                    } else {
                        isDeleting = false;
                        tTimeout = setTimeout(type, pauseTime / 2);
                    }
                }
            }
            type();
        }

        function markAsRead() {
