            stamp.style.background = 'rgba(34, 197, 94, 0.9)';
            document.getElementById('inner-message').classList.add('show');
        }

        const modal = document.getElementById('detail-modal');
        function showLocationDetail() {
            modal.classList.remove('hidden'); modal.classList.add('flex');
            setTimeout(() => modal.querySelector('.modal-content').style.transform = 'scale(1)', 10);
        }
        function closeModal() {
            modal.querySelector('.modal-content').style.transform = 'scale(0.95)';
            setTimeout(() => { modal.classList.add('hidden'); modal.classList.remove('flex'); }, 200);
        }
        modal.addEventListener('click', function(e) { if (e.target === this) closeModal(); });

        function addToastListeners() {
            document.querySelectorAll('.status-tag').forEach(tag => {
                if (tag.dataset.listenerAttached) return;
                tag.dataset.listenerAttached = 'true';

                tag.addEventListener('click', function(e) {
                    e.stopPropagation();
                    const info = this.querySelector('.tooltip')?.textContent;
                    if (info && window.matchMedia("(pointer: coarse)").matches) {
