                        toast.className = 'fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-amber-900 text-white px-6 py-3 rounded-lg text-sm z-[3000] shadow-xl font-sans text-center';
                        toast.style.fontFamily = '"LXGW WenKai Mono", monospace';
                        toast.textContent = info;
