        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 20px;
            width: 100%;
        }

        /* 背景音频 */
        #backgroundMusic {
            display: none;
        }

        /* 主题切换按钮 */
        .theme-toggle {
            position: fixed;
            top: 20px;
            right: 20px;
            width: 60px;
            height: 60px;
            border-radius: 50%;
            border: none;
            cursor: pointer;
            font-size: 24px;
            z-index: 1000;
            transition: all 0.5s ease;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
        }

        .light-mode .theme-toggle {
            background: linear-gradient(45deg, #d4a574, #c19a6b);
            color: #3d3528;
        }

        .light-mode .theme-toggle:hover {
            background: linear-gradient(45deg, #c19a6b, #b8935f);
            transform: scale(1.1) rotate(15deg);
        }

        .dark-mode .theme-toggle {
            background: linear-gradient(45deg, #74b9ff, #0984e3);
            color: #ffffff;
        }

        .dark-mode .theme-toggle:hover {
            background: linear-gradient(45deg, #0984e3, #0066cc);
            transform: scale(1.1) rotate(-15deg);
        }

        /* 工具栏 */
        .toolbar {
            position: fixed;
            left: 20px;
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 10px;
            z-index: 1000;
        }

        .tool-btn {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            border: none;
            cursor: pointer;
            font-size: 20px;
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
            position: relative;
        }

        .light-mode .tool-btn {
            background: rgba(212, 165, 116, 0.9);
            color: #3d3528;
        }

        .light-mode .tool-btn:hover {
            background: rgba(193, 154, 107, 1);
            transform: scale(1.1);
        }

        .dark-mode .tool-btn {
            background: rgba(22, 33, 62, 0.9);
            color: #ffd700;
        }

        .dark-mode .tool-btn:hover {
            background: rgba(255, 215, 0, 0.2);
            transform: scale(1.1);
        }

        /* 工具提示 */
        .tool-btn .tooltip {
            position: absolute;
            left: 60px;
            top: 50%;
            transform: translateY(-50%);
            background: rgba(0, 0, 0, 0.8);
            color: white;
            padding: 5px 10px;
            border-radius: 5px;
            font-size: 12px;
            white-space: nowrap;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.3s ease;
        }

        .tool-btn:hover .tooltip {
            opacity: 1;
        }

        /* 复制成功提示 */
        .copy-toast {
            position: fixed;
            bottom: 30px;
            right: 30px;
            padding: 12px 20px;
            border-radius: 8px;
            font-size: 14px;
            z-index: 2000;
            animation: slideInUp 0.3s ease, fadeOut 0.3s ease 2s forwards;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
            max-width: 250px;
            word-wrap: break-word;
        }

        .light-mode .copy-toast {
            background: #d4a574;
            color: #3d3528;
        }

        .dark-mode .copy-toast {
            background: #ffd700;
            color: #1a1a2e;
        }

        @keyframes slideInUp {
            from { transform: translateY(100%); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
        }

        @keyframes fadeOut {
            to { opacity: 0; transform: translateY(-20px); }
        }

        /* 顶部标题区域 */
        .header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 50px;
            padding: 30px 20px;
            border-radius: 20px;
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
            transition: all 0.5s ease;
            width: 100%;
            flex-wrap: wrap;
            gap: 20px;
        }

        .light-mode .header {
            background: rgba(245, 240, 232, 0.8);
            border-color: rgba(61, 53, 40, 0.1);
        }

        .dark-mode .header {
            background: rgba(22, 33, 62, 0.6);
            border-color: rgba(255, 255, 255, 0.1);
        }

        .title {
            font-size: 48px;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.3s ease;
            text-shadow: 2px 2px 4px rgba(255, 215, 0, 0.3);
            position: relative;
            flex-shrink: 0;
        }

        .light-mode .title {
            background: linear-gradient(45deg, #8b5a3c, #d4a574);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .dark-mode .title {
            background: linear-gradient(45deg, #ffd700, #ffb347);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .title:hover {
            transform: scale(1.05);
            filter: brightness(1.2);
        }

        /* 标题特效 */
        .title:hover::after {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(45deg, transparent 30%, rgba(255, 255, 255, 0.3) 50%, transparent 70%);
            animation: shine 0.8s ease;
        }

        @keyframes shine {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }

        .commands {
            font-size: 14px;
            text-align: right;
            line-height: 1.8;
            transition: all 0.5s ease;
            flex-shrink: 1;
            min-width: 0;
        }

        .light-mode .commands {
            color: #5d5245;
        }

        .dark-mode .commands {
            color: #b8b8b8;
        }

        .commands div:first-child {
            font-weight: bold;
            margin-bottom: 8px;
            font-size: 16px;
        }

        .light-mode .commands div:first-child {
            color: #8b5a3c;
        }

        .dark-mode .commands div:first-child {
            color: #ffd700;
        }

        .commands div:not(:first-child) {
            cursor: pointer;
            padding: 2px 8px;
            border-radius: 4px;
            transition: all 0.3s ease;
            position: relative;
            word-break: break-all;
        }

        .light-mode .commands div:not(:first-child):hover {
            background: rgba(139, 90, 60, 0.2);
            color: #8b5a3c;
        }

        .dark-mode .commands div:not(:first-child):hover {
            background: rgba(255, 215, 0, 0.2);
            color: #ffd700;
        }

        /* 导航书签 */
        .nav-tabs {
            display: flex;
            justify-content: center;
            margin-bottom: 40px;
            border-radius: 15px;
            padding: 10px;
            backdrop-filter: blur(10px);
            transition: all 0.5s ease;
            flex-wrap: wrap;
            gap: 5px;
            width: 100%;
        }

        .light-mode .nav-tabs {
            background: rgba(245, 240, 232, 0.9);
        }

        .dark-mode .nav-tabs {
            background: rgba(12, 12, 12, 0.8);
        }

        .tab-btn {
            padding: 12px 20px;
            margin: 0 2px;
            background: transparent;
            border: none;
            cursor: pointer;
            border-radius: 10px;
            font-size: 16px;
            font-weight: 500;
            transition: all 0.4s ease;
            position: relative;
            overflow: hidden;
            font-family: "江城正君体 400W", 'Microsoft YaHei', Arial, sans-serif;
            flex-shrink: 0;
            white-space: nowrap;
        }

        .light-mode .tab-btn {
            color: #5d5245;
        }

        .dark-mode .tab-btn {
            color: #b8b8b8;
        }

        .tab-btn:before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            transition: left 0.5s;
        }

        .light-mode .tab-btn:before {
            background: linear-gradient(90deg, transparent, rgba(139, 90, 60, 0.2), transparent);
        }

        .dark-mode .tab-btn:before {
            background: linear-gradient(90deg, transparent, rgba(255, 215, 0, 0.2), transparent);
        }

        .tab-btn:hover:before {
            left: 100%;
        }

        .tab-btn.active {
            font-weight: 700;
            box-shadow: 0 5px 15px rgba(255, 215, 0, 0.4);
        }

        .light-mode .tab-btn.active {
            background: linear-gradient(45deg, #8b5a3c, #d4a574);
            color: #ffffff;
        }

        .dark-mode .tab-btn.active {
            background: linear-gradient(45deg, #ffd700, #ffb347);
            color: #1a1a2e;
        }

        /* 内容区域 */
        .content {
            min-height: 600px;
            border-radius: 20px;
            padding: 20px;
            backdrop-filter: blur(15px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);
            transition: all 0.5s ease;
            width: 100%;
        }

        .light-mode .content {
            background: rgba(245, 240, 232, 0.8);
            border-color: rgba(61, 53, 40, 0.1);
        }

        .dark-mode .content {
            background: rgba(22, 33, 62, 0.4);
            border-color: rgba(255, 255, 255, 0.1);
        }

        .tab-content {
            display: none;
            animation: fadeInUp 0.6s ease;
        }

        .tab-content.active {
            display: block;
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* 人设信息样式 */
        .profile-section {
            margin-bottom: 35px;
        }

        .section-title {
            font-size: 24px;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 2px solid rgba(255, 215, 0, 0.3);
            position: relative;
            transition: all 0.5s ease;
            cursor: pointer;
            word-wrap: break-word;
        }

        .light-mode .section-title {
            color: #8b5a3c;
        }

        .dark-mode .section-title {
            color: #ffd700;
        }

        .section-title:after {
            content: '';
            position: absolute;
            bottom: -2px;
            left: 0;
            width: 60px;
            height: 2px;
            transition: all 0.5s ease;
        }

        .light-mode .section-title:after {
            background: #8b5a3c;
        }

        .dark-mode .section-title:after {
            background: #ffd700;
        }

        .section-title:hover:after {
            width: 120px;
        }

        .profile-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 25px;
            margin-bottom: 30px;
            width: 100%;
        }

        .profile-item {
            padding: 25px 20px;
            border-radius: 15px;
            border-left: 4px solid;
            transition: all 0.3s ease;
            cursor: pointer;
            word-wrap: break-word;
            overflow-wrap: break-word;
            width: 100%;
        }

        .light-mode .profile-item {
            background: rgba(255, 255, 255, 0.6);
            border-left-color: #8b5a3c;
            box-shadow: 0 4px 15px rgba(139, 90, 60, 0.1);
        }

        .dark-mode .profile-item {
            background: rgba(12, 12, 12, 0.6);
            border-left-color: #ffd700;
        }

        .profile-item:hover {
            transform: translateY(-5px) scale(1.02);
        }

        .light-mode .profile-item:hover {
            box-shadow: 0 10px 25px rgba(139, 90, 60, 0.2);
            background: rgba(255, 255, 255, 0.8);
        }

        .dark-mode .profile-item:hover {
            box-shadow: 0 10px 25px rgba(255, 215, 0, 0.2);
        }

        .item-label {
            font-size: 16px;
            font-weight: bold;
            margin-bottom: 8px;
            transition: all 0.5s ease;
            word-wrap: break-word;
        }

        .light-mode .item-label {
            color: #8b5a3c;
        }

        .dark-mode .item-label {
            color: #ffd700;
        }

        .item-content {
            line-height: 1.7;
            transition: all 0.5s ease;
            word-wrap: break-word;
            overflow-wrap: break-word;
        }

        .light-mode .item-content {
            color: #3d3528;
        }

        .dark-mode .item-content {
            color: #e8e8e8;
        }

        /* 开场白样式 */
        .scenario-item {
            margin-bottom: 20px;
            padding: 20px;
            border-radius: 15px;
            border: 1px solid;
            cursor: pointer;
            transition: all 0.4s ease;
            position: relative;
            overflow: hidden;
            word-wrap: break-word;
            overflow-wrap: break-word;
        }

        .light-mode .scenario-item {
            background: rgba(255, 255, 255, 0.6);
            border-color: rgba(139, 90, 60, 0.3);
        }

        .dark-mode .scenario-item {
            background: rgba(12, 12, 12, 0.7);
            border-color: rgba(255, 215, 0, 0.2);
        }

        .scenario-item:before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            transition: left 0.6s;
        }

        .light-mode .scenario-item:before {
            background: linear-gradient(90deg, transparent, rgba(139, 90, 60, 0.1), transparent);
        }

        .dark-mode .scenario-item:before {
            background: linear-gradient(90deg, transparent, rgba(255, 215, 0, 0.1), transparent);
        }

        .scenario-item:hover:before {
            left: 100%;
        }

        .scenario-item:hover {
            transform: translateY(-3px) scale(1.01);
        }

        .light-mode .scenario-item:hover {
            background: rgba(139, 90, 60, 0.05);
            border-color: #8b5a3c;
            box-shadow: 0 8px 20px rgba(139, 90, 60, 0.2);
        }

        .dark-mode .scenario-item:hover {
            background: rgba(255, 215, 0, 0.05);
            border-color: #ffd700;
            box-shadow: 0 8px 20px rgba(255, 215, 0, 0.2);
        }

        .scenario-number {
            font-size: 18px;
            font-weight: bold;
            margin-bottom: 15px;
            transition: all 0.5s ease;
            word-wrap: break-word;
        }

        .light-mode .scenario-number {
            color: #8b5a3c;
        }

        .dark-mode .scenario-number {
            color: #ffd700;
        }

        .scenario-content {
            line-height: 1.8;
            text-align: justify;
            transition: all 0.5s ease;
            word-wrap: break-word;
            overflow-wrap: break-word;
            padding-right: 40px;
        }

        .light-mode .scenario-content {
            color: #3d3528;
        }

        .dark-mode .scenario-content {
            color: #e8e8e8;
        }

        /* 彩蛋效果 */
        .easter-egg {
            position: fixed;
            pointer-events: none;
            font-size: 20px;
            z-index: 1000;
            animation: float 2s ease-out forwards;
        }

        @keyframes float {
            0% {
                transform: translateY(0) rotate(0deg);
                opacity: 1;
            }
            100% {
                transform: translateY(-100px) rotate(360deg);
                opacity: 0;
            }
        }

        /* 背景粒子效果 */
        .particle {
            position: fixed;
            pointer-events: none;
            width: 2px;
            height: 2px;
            border-radius: 50%;
            animation: sparkle 3s linear infinite;
        }

        .light-mode .particle {
            background: #d4a574;
        }

        .dark-mode .particle {
            background: #ffd700;
        }

        @keyframes sparkle {
            0%, 100% { opacity: 0; transform: translateY(0); }
            50% { opacity: 1; }
            100% { transform: translateY(-100vh); }
        }

        /* 鼠标跟随效果 */
        .mouse-follower {
            position: fixed;
            width: 20px;
            height: 20px;
            border-radius: 50%;
            pointer-events: none;
            z-index: 999;
            transition: all 0.1s ease;
            mix-blend-mode: difference;
        }

        .light-mode .mouse-follower {
            background: rgba(139, 90, 60, 0.3);
        }

        .dark-mode .mouse-follower {
            background: rgba(255, 215, 0, 0.3);
        }

        /* 特殊关系项目样式 */
        .profile-item.special-relationship {
            border-left-color: #ff6b6b !important;
        }

        .light-mode .profile-item.special-relationship {
            border-left-color: #c0392b !important;
        }

        /* 特殊场景样式 */
        .scenario-item.special-scenario {
            background: linear-gradient(45deg, rgba(255, 215, 0, 0.1), rgba(255, 179, 71, 0.1)) !important;
        }

        .light-mode .scenario-item.special-scenario {
            background: linear-gradient(45deg, rgba(139, 90, 60, 0.1), rgba(212, 165, 116, 0.1)) !important;
        }

        /* 音效提示 */
        .sound-wave {
            position: absolute;
            top: 50%;
            left: 50%;
            width: 100px;
            height: 100px;
            border: 2px solid;
            border-radius: 50%;
            transform: translate(-50%, -50%);
            animation: soundWave 1s ease-out forwards;
            pointer-events: none;
        }

        .light-mode .sound-wave {
            border-color: rgba(139, 90, 60, 0.6);
        }

        .dark-mode .sound-wave {
            border-color: rgba(255, 215, 0, 0.6);
        }

        @keyframes soundWave {
            0% {
                transform: translate(-50%, -50%) scale(0);
                opacity: 1;
            }
            100% {
                transform: translate(-50%, -50%) scale(3);
                opacity: 0;
            }
        }

        /* 场景图标动画 */
        .scenario-icon {
            position: absolute;
            top: 50%;
            right: 20px;
            transform: translateY(-50%);
            font-size: 24px;
            opacity: 0;
            transition: all 0.3s ease;
            animation: bounceIn 0.5s ease forwards;
        }

        @keyframes bounceIn {
            0% {
                transform: translateY(-50%) scale(0);
                opacity: 0;
            }
            60% {
                transform: translateY(-50%) scale(1.3);
                opacity: 1;
            }
            100% {
                transform: translateY(-50%) scale(1);
                opacity: 1;
            }
        }

        /* 音乐播放状态指示 */
        .music-indicator {
            position: absolute;
            top: -5px;
            right: -5px;
            width: 15px;
            height: 15px;
            background: #00ff00;
            border-radius: 50%;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .music-indicator.playing {
            opacity: 1;
            animation: pulse 1.5s infinite;
        }

        @keyframes pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.3); }
        }

        /* 手机端响应式设计 */
        @media (max-width: 768px) {
            .container {
                padding: 20px 10px;
                margin: 0;
                max-width: 100%;
            }

            /* 标题区域移动端适配 */
            .header {
                flex-direction: column;
                text-align: center;
                padding: 20px 15px;
                margin-bottom: 30px;
            }

            .title {
                font-size: 32px;
                margin-bottom: 15px;
            }

            .commands {
                text-align: center;
                font-size: 12px;
                width: 100%;
            }

            .commands div:first-child {
                font-size: 14px;
            }

            .commands div:not(:first-child) {
                word-break: break-all;
                margin: 2px 0;
                padding: 4px 6px;
            }

            /* 导航栏移动端适配 */
            .nav-tabs {
                padding: 8px;
                margin-bottom: 30px;
                justify-content: center;
            }

            .tab-btn {
                padding: 8px 12px;
                font-size: 14px;
                margin: 2px;
                min-width: auto;
            }

            /* 内容区域移动端适配 */
            .content {
                padding: 15px;
                margin: 0;
            }

            /* 人设信息移动端适配 */
            .profile-grid {
                grid-template-columns: 1fr;
                gap: 15px;
            }

            .profile-item {
                padding: 15px;
                margin: 0;
            }

            .section-title {
                font-size: 20px;
            }

            .item-label {
                font-size: 14px;
            }

            .item-content {
                font-size: 13px;
                line-height: 1.6;
            }

            /* 场景移动端适配 */
            .scenario-item {
                padding: 15px;
                margin-bottom: 15px;
            }

            .scenario-number {
                font-size: 16px;
                margin-bottom: 10px;
            }

            .scenario-content {
                font-size: 13px;
                line-height: 1.6;
                padding-right: 15px;
            }

            .scenario-icon {
                right: 10px;
                font-size: 20px;
            }

            /* 工具栏移动端适配 */
            .toolbar {
                left: 5px;
                top: 30%;
                gap: 8px;
            }

            .tool-btn {
                width: 40px;
                height: 40px;
                font-size: 16px;
            }

            .tool-btn .tooltip {
                left: 45px;
                font-size: 10px;
                padding: 3px 6px;
            }

            /* 主题切换按钮移动端适配 */
            .theme-toggle {
                width: 45px;
                height: 45px;
                font-size: 20px;
                top: 10px;
                right: 10px;
            }

            /* 提示信息移动端适配 */
            .copy-toast {
                bottom: 20px;
                right: 10px;
                left: 10px;
                max-width: none;
                font-size: 12px;
                padding: 10px 15px;
                text-align: center;
            }

            /* 鼠标跟随效果在移动端隐藏 */
            .mouse-follower {
                display: none;
            }

            /* 移动端禁用hover效果 */
            .profile-item:hover,
            .scenario-item:hover,
            .section-title:hover,
            .tab-btn:hover,
            .tool-btn:hover,
            .theme-toggle:hover {
                transform: none;
                box-shadow: inherit;
            }

            .tab-btn:hover:before,
            .scenario-item:hover:before {
                left: -100%;
            }

            .section-title:hover:after {
                width: 60px;
            }
        }

        /* 超小屏幕适配 (宽度小于480px) */
        @media (max-width: 480px) {
            .container {
                padding: 15px 8px;
            }

            .header {
                padding: 15px 10px;
            }

            .title {
                font-size: 28px;
            }

            .commands {
                font-size: 11px;
            }

            .tab-btn {
                padding: 6px 8px;
                font-size: 12px;
            }

            .content {
                padding: 12px;
            }

            .profile-item,
            .scenario-item {
