    <script>
        let isFullScreen = false;
        let musicEnabled = false;
        let backgroundMusic = document.getElementById('backgroundMusic');
        let musicIndicator = document.getElementById('musicIndicator');

        // 主题切换功能
        function toggleTheme() {
            const body = document.body;
            const themeIcon = document.getElementById('theme-icon');

            if (body.classList.contains('light-mode')) {
                body.classList.remove('light-mode');
                body.classList.add('dark-mode');
                themeIcon.textContent = '🌙';
                createEasterEgg(event, '🌙');
            } else {
                body.classList.remove('dark-mode');
                body.classList.add('light-mode');
                themeIcon.textContent = '☀️';
                createEasterEgg(event, '☀️');
            }

            // 切换时的粒子效果
            createParticles();
        }

        // 页面切换功能
        function switchTab(tabName) {
            // 隐藏所有内容
            const contents = document.querySelectorAll('.tab-content');
            contents.forEach(content => content.classList.remove('active'));

            // 移除所有按钮的激活状态
            const buttons = document.querySelectorAll('.tab-btn');
            buttons.forEach(btn => btn.classList.remove('active'));

            // 显示选中的内容
            document.getElementById(tabName).classList.add('active');

            // 激活对应按钮
            event.target.classList.add('active');

            // 创建切换特效
            createParticles();
        }

        // 复制到剪切板功能
        function copyToClipboard(text) {
            navigator.clipboard.writeText(text).then(function() {
                showCopyToast('已复制到剪切板！');
                createEasterEgg(event, '📋');
            }).catch(function(err) {
                // 备用方案
                const textArea = document.createElement('textarea');
                textArea.value = text;
                document.body.appendChild(textArea);
                textArea.select();
                document.execCommand('copy');
                document.body.removeChild(textArea);
                showCopyToast('已复制到剪切板！');
                createEasterEgg(event, '📋');
            });
        }

        // 显示复制成功提示
        function showCopyToast(message) {
            const toast = document.createElement('div');
            toast.className = 'copy-toast';
            toast.textContent = message;
            document.body.appendChild(toast);

            setTimeout(() => {
                if (toast.parentNode) {
                    toast.parentNode.removeChild(toast);
                }
            }, 2500);
        }

        // 随机场景功能
        function randomScenario() {
            const scenarios = document.querySelectorAll('.scenario-item');
            const randomIndex = Math.floor(Math.random() * scenarios.length);

            // 先切换到场景页面
            switchTab('scenarios');

            // 延迟后滚动到随机场景
            setTimeout(() => {
                scenarios[randomIndex].scrollIntoView({ 
                    behavior: 'smooth',
                    block: 'center'
                });
                scenarios[randomIndex].style.animation = 'none';
                scenarios[randomIndex].offsetHeight; // 触发重排
                scenarios[randomIndex].style.animation = 'fadeInUp 0.6s ease';

                createEasterEgg(event, '🎲');
            }, 300);
        }

        // 背景音乐切换
        function toggleMusic() {
            const musicBtn = document.getElementById('musicBtn');
            musicEnabled = !musicEnabled;

            if (musicEnabled) {
                backgroundMusic.play().then(() => {
                    musicBtn.textContent = '🔊';
                    musicBtn.querySelector('.tooltip').textContent = '关闭音乐';
                    musicIndicator.classList.add('playing');
                }).catch(err => {
                    console.log('音频播放失败:', err);
                    musicEnabled = false;
                });
            } else {
                backgroundMusic.pause();
                musicBtn.textContent = '🔇';
                musicBtn.querySelector('.tooltip').textContent = '开启音乐';
                musicIndicator.classList.remove('playing');
            }

            createEasterEgg(event, musicEnabled ? '🎵' : '🔇');
        }

        // 重置特效
        function resetEffects() {
            // 清除所有粒子
            const particles = document.querySelectorAll('.particle');
            particles.forEach(particle => {
                if (particle.parentNode) {
                    particle.parentNode.removeChild(particle);
                }
            });

            // 清除所有彩蛋
            const easterEggs = document.querySelectorAll('.easter-egg');
            easterEggs.forEach(egg => {
                if (egg.parentNode) {
                    egg.parentNode.removeChild(egg);
                }
            });

            // 重新启动粒子效果
            createParticles();
            showCopyToast('特效已重置！');
            createEasterEgg(event, '🎨');
        }

        // 专注模式
        function fullScreenMode() {
            const container = document.querySelector('.container');
            const toolbar = document.querySelector('.toolbar');
            const themeToggle = document.querySelector('.theme-toggle');

            isFullScreen = !isFullScreen;

            if (isFullScreen) {
                toolbar.style.opacity = '0.3';
                themeToggle.style.opacity = '0.3';
                container.style.maxWidth = '100vw';
                container.style.padding = '20px';
                showCopyToast('专注模式已开启');
                createEasterEgg(event, '🎯');
            } else {
                toolbar.style.opacity = '1';
                themeToggle.style.opacity = '1';
                container.style.maxWidth = '1200px';
                container.style.padding = '40px 20px';
                showCopyToast('专注模式已关闭');
                createEasterEgg(event, '🔄');
            }
        }

        // 彩蛋效果
        function createEasterEgg(event, emoji) {
            const body = document.body;
            const isDark = body.classList.contains('dark-mode');

            const easterEgg = document.createElement('div');
            easterEgg.className = 'easter-egg';
            easterEgg.textContent = emoji;
            easterEgg.style.left = event.clientX + 'px';
            easterEgg.style.top = event.clientY + 'px';
            easterEgg.style.color = isDark ? '#ffd700' : '#d4a574';

            document.body.appendChild(easterEgg);

            setTimeout(() => {
                if (easterEgg.parentNode) {
                    easterEgg.parentNode.removeChild(easterEgg);
                }
            }, 2000);
        }

        // 场景图标效果（点击时出现图标）
        function createScenarioIcon(event, emoji) {
            // 创建临时图标元素
            const icon = document.createElement('div');
            icon.className = 'scenario-icon';
            icon.textContent = emoji;
            icon.style.opacity = '1';

            // 添加到点击的场景元素中
            const scenario = event.currentTarget;
            scenario.appendChild(icon);

            // 1秒后移除图标
            setTimeout(() => {
                if (icon.parentNode) {
                    icon.parentNode.removeChild(icon);
                }
            }, 1000);

            // 同时创建彩蛋效果
            createEasterEgg(event, emoji);
        }

        // 音波效果
        function createSoundWave(event) {
            const soundWave = document.createElement('div');
            soundWave.className = 'sound-wave';
            event.currentTarget.appendChild(soundWave);

            setTimeout(() => {
                if (soundWave.parentNode) {
                    soundWave.parentNode.removeChild(soundWave);
                }
            }, 1000);
        }

        // 粒子效果
        function createParticles() {
            for (let i = 0; i < 20; i++) {
                setTimeout(() => {
                    const particle = document.createElement('div');
                    particle.className = 'particle';
                    particle.style.left = Math.random() * window.innerWidth + 'px';
                    particle.style.top = window.innerHeight + 'px';
                    particle.style.animationDelay = Math.random() * 2 + 's';

                    document.body.appendChild(particle);

                    setTimeout(() => {
                        if (particle.parentNode) {
                            particle.parentNode.removeChild(particle);
                        }
                    }, 3000);
                }, i * 100);
            }
        }

        // 鼠标跟随效果
        function setupMouseFollower() {
            const follower = document.getElementById('mouseFollower');
            let mouseX = 0, mouseY = 0;
            let followerX = 0, followerY = 0;

            document.addEventListener('mousemove', (e) => {
                mouseX = e.clientX;
                mouseY = e.clientY;
            });

            function updateFollower() {
                followerX += (mouseX - followerX) * 0.1;
                followerY += (mouseY - followerY) * 0.1;

                follower.style.left = followerX - 10 + 'px';
                follower.style.top = followerY - 10 + 'px';

                requestAnimationFrame(updateFollower);
            }

            updateFollower();
        }

        // 音频加载事件监听
        backgroundMusic.addEventListener('loadeddata', () => {
            console.log('音频加载完成');
        });

        backgroundMusic.addEventListener('error', (e) => {
            console.log('音频加载错误:', e);
        });

        // 检测是否为移动设备
        function isMobile() {
            return window.innerWidth <= 768 || /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
        }

        // 初始化粒子效果
        if (!isMobile()) {
            setInterval(createParticles, 10000);
        }

        // 页面加载完成后的特效
        window.addEventListener('load', () => {
            if (!isMobile()) {
                createParticles();
                setupMouseFollower();
            }

            // 预加载音频
            backgroundMusic.load();

            // 标题闪烁效果（只在桌面端）
            if (!isMobile()) {
                const title = document.querySelector('.title');
                setInterval(() => {
                    const body = document.body;
                    const isDark = body.classList.contains('dark-mode');

                    if (isDark) {
                        title.style.textShadow = '2px 2px 4px rgba(255, 215, 0, 0.8), 0 0 20px rgba(255, 215, 0, 0.3)';
                    } else {
                        title.style.textShadow = '2px 2px 4px rgba(139, 90, 60, 0.8), 0 0 20px rgba(139, 90, 60, 0.3)';
                    }

                    setTimeout(() => {
                        title.style.textShadow = '2px 2px 4px rgba(255, 215, 0, 0.3)';
                    }, 500);
                }, 5000);
            }
        });

        // 键盘快捷键（只在桌面端）
        if (!isMobile()) {
            document.addEventListener('keydown', (e) => {
                if (e.ctrlKey || e.metaKey) {
                    switch(e.key) {
                        case '1':
                            e.preventDefault();
                            switchTab('basic');
                            break;
                        case '2':
                            e.preventDefault();
                            switchTab('personality');
                            break;
                        case '3':
                            e.preventDefault();
                            switchTab('relationships');
                            break;
                        case '4':
                            e.preventDefault();
                            switchTab('philosophy');
                            break;
                        case '5':
                            e.preventDefault();
                            switchTab('scenarios');
                            break;
                        case 'd':
                            e.preventDefault();
                            toggleTheme();
                            break;
                        case 'r':
                            e.preventDefault();
                            randomScenario();
                            break;
                        case 'm':
                            e.preventDefault();
                            toggleMusic();
                            break;
                    }
                }
            });
        }

        // 移动端触摸优化
        if (isMobile()) {
            // 禁用移动端的默认触摸行为，防止意外缩放
            document.addEventListener('touchstart', function(e) {
                if (e.touches.length > 1) {
                    e.preventDefault();
                }
            }, { passive: false });

            // 移动端双击禁用
            let lastTouchEnd = 0;
            document.addEventListener('touchend', function(e) {
                let now = (new Date()).getTime();
                if (now - lastTouchEnd <= 300) {
                    e.preventDefault();
                }
                lastTouchEnd = now;
            }, false);
        }

        // 窗口大小改变时重新检测设备类型
        window.addEventListener('resize', () => {
            // 重新检测是否为移动设备
            const wasMobile = document.body.classList.contains('mobile-device');
            const nowMobile = isMobile();

            if (wasMobile !== nowMobile) {
                if (nowMobile) {
                    document.body.classList.add('mobile-device');
                    // 停止桌面端特效
                    const particles = document.querySelectorAll('.particle');
                    particles.forEach(p => p.remove());
                } else {
                    document.body.classList.remove('mobile-device');
                    // 重启桌面端特效
                    createParticles();
                    setupMouseFollower();
                }
            }
        });
    </script>
</body>
</html>
